insert into public.restaurants(name,slug,active,delivery_fee_cents) values ('NSS Burger — Demonstração','nss-burger',true,500);
insert into public.categories(restaurant_id,name) select r.id,c.name from public.restaurants r cross join (values ('Hambúrgueres artesanais'),('Combos especiais'),('Porções'),('Bebidas e sobremesas')) c(name) where r.slug='nss-burger';
insert into public.products(restaurant_id,category_id,name,description,price_cents) select r.id,c.id,v.name,v.description,v.price from (values ('Hambúrgueres artesanais','Classic Burger','Carne bovina, queijo, alface, tomate e molho especial.',2490),('Hambúrgueres artesanais','NSS Bacon','Hambúrguer artesanal, cheddar e bacon crocante.',2990),('Hambúrgueres artesanais','Double Smash','Dois hambúrgueres, cheddar duplo e molho da casa.',3490),('Hambúrgueres artesanais','Chicken Crispy','Frango crocante, alface e maionese especial.',2690),('Combos especiais','Combo Individual','Hambúrguer, batata frita e refrigerante.',3990),('Combos especiais','Combo Casal','Dois hambúrgueres, batata grande e dois refrigerantes.',6990),('Porções','Batata com cheddar e bacon','Porção especial da casa.',2490),('Porções','Anéis de cebola','Porção de anéis crocantes.',1690),('Bebidas e sobremesas','Refrigerante 350 ml','Lata 350 ml.',600),('Bebidas e sobremesas','Suco natural','Suco de frutas.',990),('Bebidas e sobremesas','Milk-shake','Sobremesa cremosa.',1690)) v(category,name,description,price) join public.restaurants r on r.slug='nss-burger' join public.categories c on c.restaurant_id=r.id and c.name=v.category;
